def longestStretchCovered(intervals, k):
    delta = {}
    for s, e in intervals:
        delta[s] = delta.get(s, 0) + 1
        delta[e] = delta.get(e, 0) - 1
    times = sorted(delta)
    cover = 0
    run = 0
    best = 0
    for i in range(len(times) - 1):
        cover += delta[times[i]]
        if cover >= k:
            run += times[i + 1] - times[i]
            if run > best:
                best = run
        else:
            run = 0
    return best
